294	// clean EOF or an EINTR). No prompt is ever written and the message is
295	// read to its normal end before returning.
296	HmacStatus hmacSha256Source(
297	    const std::vector<unsigned char>& key, bool fromStdin,
298	    const std::string& path,
299	    std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
300	    std::size_t& macLength) {
301	    HMAC_CTX* rawCtx = HMAC_CTX_new();
302	    if (rawCtx == nullptr) {
303	        return HmacStatus::kCryptoError;
304	    }
305	    std::unique_ptr<HMAC_CTX, decltype(&HMAC_CTX_free)> ctx(rawCtx,
306	                                                            HMAC_CTX_free);
307	
308	    // Init with the key and SHA-256. HMAC_Init_ex performs the standard
309	    // RFC 2104 key normalization itself, so keys longer than the SHA-256
310	    // block size are hashed exactly as the standard requires; the resulting
311	    // tag is identical to the one-shot HMAC() interface on both OpenSSL
312	    // 1.1.1 and OpenSSL 3.x. The key is validated to be non-empty before
313	    // this is called, so key.data() is always valid.
314	    if (HMAC_Init_ex(ctx.get(), key.data(), static_cast<int>(key.size()),
315	                     EVP_sha256(), nullptr) != 1) {
316	        return HmacStatus::kCryptoError;
317	    }
318	
319	    std::array<char, 65536> buffer{};
320	    HmacStatus readStatus;
321	    if (fromStdin) {
322	        // File descriptor 0 is consumed exactly as it arrives: no prompt is
323	        // written, and no result is emitted before this returns at the
324	        // descriptor's normal end. How the bytes are split across reads
325	        // (pipe scheduling, redirection chunking) cannot change the tag.
326	        readStatus = streamHmac(
327	            ctx.get(), buffer,
328	            [](char* buf, std::size_t count) {
329	                return ::read(STDIN_FILENO, buf, count);
330	            });
331	    } else {
332	        std::ifstream in(path, std::ios::binary | std::ios::in);
333	        if (!in) {
