339	        // error). The trailing short final read is just another non-zero
340	        // count, so every byte -- including a final partial chunk -- takes
341	        // part exactly once.
342	        readStatus = streamHmac(ctx.get(), buffer,
343	                                [&in](char* buf, std::size_t count) -> ssize_t {
344	            in.read(buf, static_cast<std::streamsize>(count));
345	            std::streamsize got = in.gcount();
346	            if (got > 0) {
347	                return static_cast<ssize_t>(got);
348	            }
